    y: Math.round(Math.sin(angle) * radius + seededOffset(index, 1) * 24)
  };
}

function seededOffset(index, salt) {
  const n = Math.sin((index + 1) * 127.1 + salt * 311.7) * 43758.5453;
  return (n - Math.floor(n)) * 2 - 1;
}

