export const libraryAtlasDefs = Object.freeze([
  ...BIOMES.map(biome => ({
    id: `${biome}_base_tiles`,
    src: `assets/generated/terrain/base/${biome}_base_tiles.png`,
    cell: 32,
    frames: 8,
    rows: Array.from({ length: 8 }, (_, row) => ({ id: `${biome}_base_${row}`, row, frames: 8 }))
