  ...BIOMES.map(biome => ({
    id: `${biome}_nature_objects`,
    src: `assets/generated/objects/nature/${biome}_nature_objects.png`,
    cell: 32,
    frames: 8,
    rows: NATURE_ROWS.map((name, row) => ({ id: `${biome}_${name}`, row, frames: 8 }))
  }))
]);

