export const BODY_PARTS = Object.freeze([
  'shadow', 'back_hair', 'back_equipment', 'rear_upper_arm', 'rear_forearm', 'rear_hand',
  'rear_thigh', 'rear_shin', 'rear_foot', 'hips', 'torso', 'neck', 'head', 'face',
  'front_thigh', 'front_shin', 'front_foot', 'front_upper_arm', 'front_forearm', 'front_hand',
  'front_hair', 'clothing_torso', 'clothing_legs', 'armor', 'held_item', 'equipment_effect', 'lighting_mask'
]);

export const BODY_DIRECTIONS = Object.freeze(['S', 'SE', 'E', 'NE', 'N', 'NW', 'W', 'SW']);

export const BODY_ANIMATIONS = Object.freeze([
  'idle', 'walk', 'sprint', 'jump_start', 'jump_air', 'land', 'climb', 'climb_idle',
  'glide_start', 'glide_loop', 'glide_land', 'dodge_roll', 'attack', 'cast', 'gather', 'carry', 'hurt'
]);

export function bodyFrameId(part, direction, animation) {
  return `humanoid_${part}_${direction}_${animation}`;
}

import { BODY_PARTS } from './body-schema.js';

export class ModularCharacter {
  constructor() {
    this.direction = 'S';
    this.animation = 'idle';
    this.frame = 0;
    this.parts = new Map(BODY_PARTS.map(part => [part, { id: part, tint: null, visible: true }]));
  }

  setMotion({ moving = false, sprinting = false, jumping = false, climbing = false, gliding = false, rolling = false, direction = this.direction } = {}) {
    this.direction = direction;
    if (rolling) this.animation = 'dodge_roll';
    else if (gliding) this.animation = 'glide_loop';
    else if (climbing) this.animation = moving ? 'climb' : 'climb_idle';
    else if (jumping) this.animation = 'jump_air';
    else if (sprinting) this.animation = 'sprint';
    else if (moving) this.animation = 'walk';
    else this.animation = 'idle';
  }

  update(dt) {
    const fps = this.animation === 'idle' ? 3 : this.animation === 'dodge_roll' ? 14 : 8;
    this.frame = (this.frame + dt * fps) % 8;
  }
}

